        { label: 'Dr. Sarah Chen', type: 'doctor' },
        { label: 'Dr. Michael Rodriguez', type: 'doctor' },
        { label: 'Dr. Emily Park', type: 'doctor' }
      ];

      var queryInput = document.getElementById('query');
      var dropdown = document.getElementById('autocompleteDropdown');
      var highlightedIdx = -1;

      queryInput.addEventListener('input', function() {
        var val = this.value.trim().toLowerCase();
        if (val.length === 0) {
          dropdown.classList.remove('active');
          dropdown.innerHTML = '';
          highlightedIdx = -1;
          return;
        }

        var matches = suggestions.filter(function(s) {
          return s.label.toLowerCase().indexOf(val) !== -1;
        });

        if (matches.length === 0) {
          dropdown.classList.remove('active');
          dropdown.innerHTML = '';
          highlightedIdx = -1;
          return;
        }

        highlightedIdx = -1;
        var html = '';
        matches.forEach(function(item) {
          html += '<div class="autocomplete-item" data-value="' + item.label + '">' + item.label + '</div>';
        });
        dropdown.innerHTML = html;
        dropdown.classList.add('active');
      });

      queryInput.addEventListener('keydown', function(e) {
        var items = dropdown.querySelectorAll('.autocomplete-item');
        if (!items.length) return;

        if (e.key === 'ArrowDown') {
          e.preventDefault();
          highlightedIdx = Math.min(highlightedIdx + 1, items.length - 1);
          updateHighlight(items);
        } else if (e.key === 'ArrowUp') {
          e.preventDefault();
          highlightedIdx = Math.max(highlightedIdx - 1, 0);
          updateHighlight(items);
        } else if (e.key === 'Enter') {
          if (highlightedIdx >= 0 && items[highlightedIdx]) {
            e.preventDefault();
            queryInput.value = items[highlightedIdx].getAttribute('data-value');
            dropdown.classList.remove('active');
            highlightedIdx = -1;
          }
        } else if (e.key === 'Escape') {
          dropdown.classList.remove('active');
          highlightedIdx = -1;
        }
      });

      function updateHighlight(items) {
        items.forEach(function(item, i) {
          if (i === highlightedIdx) {
            item.classList.add('highlighted');
            item.scrollIntoView({ block: 'nearest' });
          } else {
            item.classList.remove('highlighted');
          }
        });
      }

      dropdown.addEventListener('click', function(e) {
        var item = e.target.closest('.autocomplete-item');
        if (item) {
          queryInput.value = item.getAttribute('data-value');
          dropdown.classList.remove('active');
          highlightedIdx = -1;
        }
      });

      document.addEventListener('click', function(e) {
        if (!queryInput.contains(e.target) && !dropdown.contains(e.target)) {
          dropdown.classList.remove('active');
          highlightedIdx = -1;
        }
      });
